												<v-row>
													<v-col cols="12" class="pb-0">
														<v-text-field outlined v-model="count" class="left-input" label="تعداد پرونده مورد نظر خود را وارد کنید" :rules="[() => Number(count) > 0 || 'تعداد پرونده را به صورت صحیح وارد کنید', () => Number(count) >= 10 || 'حداقل تعداد شارژ ۱۰ پرونده می باشد']" required />
													</v-col>
													<v-col cols="12" class="pt-0">
