													</v-col>
												</v-row>
												<div class="text-center">
													<v-btn color="success" @click="purchase(1)" variant="outlined" :loading="loading">
														قابل پرداخت: {{ String(payable).toPriceFormat() }} تومان
														<br />
														پرداخت و خرید آنلاین
													</v-btn>
												</div>
											</v-form>
										</v-card>
									</v-card-actions>
								</v-card>
							</v-col>
							<v-col cols="12" md="6">
								<v-card color="#eeeeee" theme="light">
									<v-card-title class="text-h5 justify-center mb-2">
										نامحدود یکساله (ابری)
									</v-card-title>

									<v-card-subtitle class="text-right mb-1">
										در این روش اعتبار اکانت کاربری شما به مدت یک سال شارژ می شود و می توانید به تعداد نامحدود ثبت پرونده داشته باشید و از تمام بخش های نرم افزار استفاده نمایید.
									</v-card-subtitle>
									<v-card-subtitle class="text-right mb-1">
										جهت اخذ اینماد و فعالسازی درگاه پرداخت آنلاین، امکان اتصال به دامنه اختصاصی شما و درج لینک اینماد در صفحه اختصاصی شما مهیا می باشد و می توانید با شماره پشتیبانی 09361995434 تماس حاصل فرمایید.
									</v-card-subtitle>
									<v-card-subtitle class="text-h3 text-center blue--text">قیمت: {{ permanentPrice.toString().toPriceFormat() }} تومان</v-card-subtitle>

