												<v-row>
													<v-col cols="12">
														<v-text-field outlined v-model="affCode2" class="pt-0 left-input" label="کد معرف خود را در صورت وجود وارد کنید" />
													</v-col>
												</v-row>
												<div class="text-center">
													<v-btn color="success" @click="purchase(0)" variant="outlined" :loading="loading">
