						</v-row>
					</div>
				</material-card>
			</v-col>
		</v-row>

	</v-container>
</template>

<script>
	import { get } from 'vuex-pathify'
	import api from '@/util/app-api'
	import toast from '@/util/toast'

	// Utilities
	export default {
		name: 'Buy',

		data: () => ({
			affCode1: '',
			affCode2: '',
			count: 100,
			loading: false,
			cart: {
				actionIcon: 'mdi-alert',
				actionText: '',
				color: 'red',
				icon: 'mdi-alert',
				title: '',
				route: '/admin/report-member-loans',
				value: 'خرید',
			}
		}),

		computed: {
			...get('auth', [
				'getCurrentUser',
			]),
			...get('siteConfig', [
				'permanentPrice', 'cloudPrice'
			]),
			expireDate_persian() {
				var user = this.getCurrentUser
				if (user && user.userData && user.userData.customer) {
					return `${new Date(user.userData.customer.expireDate).toLocaleDateString('fa-IR')}`
				}
				return '-----'
			},
			remainDays() {
				var user = this.getCurrentUser
				if (!user || !user.userData || !user.userData.customer)
					return 0
				const date1 = new Date()
				const date2 = new Date(user.userData.customer.expireDate)
				const diffTime = Math.max((date2 - date1), 0)
				const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24))
				return diffDays
			},
			verb() {
				return this.remainDays > 0 ? 'خواهد رسید' : 'رسیده است'
			},
			payable() {
				let price = this.count * this.cloudPrice
				// let discountPercent = Math.min(this.count / 100 * 5, 20)
				let discountPercent = 0
				price = price - (price * discountPercent / 100)
				return price
			}
		},

		mounted() {
		},
		methods: {
			purchase(productType) {
				if (!this.$refs.cloudForm.validate())
					return
				this.loading = true
				let data = {
					productType: productType,
					paymentMethod: 0,
					affCode: productType === 1 ? this.affCode1 : this.affCode2,
					loanCount: this.count
				}
				api.post('admin/purchase/create', data)
					.then(
						response => {
							window.location.replace(response)
						})
					.catch(err => {
						this.loading = false
						toast.error(err.message)
					})

			}
		},
	}
</script>
